# Not autogenerated.
"""Enforce conservative performance limits on Criterion comparison results."""

from __future__ import annotations

import argparse
import json
from pathlib import Path
from typing import TypedDict, cast


class ConfidenceInterval(TypedDict):
    """Criterion confidence interval fields used by the gate."""

    confidence_level: float
    lower_bound: float
    upper_bound: float


class Estimate(TypedDict):
    """One Criterion statistical estimate."""

    confidence_interval: ConfidenceInterval
    point_estimate: float
    standard_error: float


class ChangeEstimates(TypedDict):
    """Relevant contents of Criterion's change/estimates.json file."""

    mean: Estimate
    median: Estimate


def benchmark_name(criterion_dir: Path, estimate_path: Path) -> str:
    """Return the benchmark identifier represented by an estimates file."""
    relative_parts = estimate_path.relative_to(criterion_dir).parts
    return "/".join(relative_parts[:-2])


def scenario_name(benchmark: str) -> str:
    """Remove the final round component from a benchmark identifier."""
    return benchmark.rsplit("/", maxsplit=1)[0]


def load_change_estimates(path: Path) -> ChangeEstimates:
    """Read and type Criterion's machine-readable change estimates."""
    with path.open(encoding="utf-8") as stream:
        return cast("ChangeEstimates", json.load(stream))


def find_recent_changes(criterion_dir: Path, since: float) -> list[Path]:
    """Find comparison results written by the current benchmark invocation."""
    return sorted(
        path
        for path in criterion_dir.rglob("change/estimates.json")
        if path.stat().st_mtime >= since
    )


def verify_baseline(criterion_dir: Path, name: str, expected: int) -> int:
    """Verify that a named Criterion baseline contains every benchmark series."""
    estimates = sorted(
        path
        for path in criterion_dir.rglob("estimates.json")
        if path.parent.name == name
    )
    if len(estimates) != expected:
        print(
            f"ERROR: baseline {name!r} contains {len(estimates)} results; "
            f"expected {expected}."
        )
        return 2

    print(f"PASS: baseline {name!r} contains all {expected} benchmark results.")
    return 0


def check_regressions(
    criterion_dir: Path,
    since: float,
    expected: int,
    rounds_per_scenario: int,
    max_regression_percent: float,
) -> int:
    """Fail when most repeated intervals are wholly above the allowed limit."""
    estimate_paths = find_recent_changes(criterion_dir, since)
    if len(estimate_paths) != expected:
        print(
            f"ERROR: found {len(estimate_paths)} current comparison results; "
            f"expected {expected}."
        )
        return 2

    comparisons_by_scenario: dict[str, int] = {}
    regressions_by_scenario: dict[str, list[tuple[str, float, float, float]]] = {}
    for path in estimate_paths:
        name = benchmark_name(criterion_dir, path)
        scenario = scenario_name(name)
        comparisons_by_scenario[scenario] = comparisons_by_scenario.get(scenario, 0) + 1
        estimates = load_change_estimates(path)
        median = estimates["median"]
        lower = median["confidence_interval"]["lower_bound"] * 100
        point = median["point_estimate"] * 100
        upper = median["confidence_interval"]["upper_bound"] * 100
        if lower > max_regression_percent:
            regressions_by_scenario.setdefault(scenario, []).append(
                (name, lower, point, upper)
            )

    invalid_round_counts = {
        name: count
        for name, count in comparisons_by_scenario.items()
        if count != rounds_per_scenario
    }
    if invalid_round_counts:
        print(f"ERROR: expected {rounds_per_scenario} rounds for every scenario:")
        for name, count in sorted(invalid_round_counts.items()):
            print(f"  {name}: found {count} rounds")
        return 2

    majority = rounds_per_scenario // 2 + 1
    regressions = {
        name: estimates
        for name, estimates in regressions_by_scenario.items()
        if len(estimates) >= majority
    }

    if regressions:
        print(
            "FAIL: a majority of repeated benchmark intervals exceeded "
            f"the {max_regression_percent:.2f}% limit:"
        )
        for scenario, estimates in sorted(regressions.items()):
            print(f"  {scenario}: {len(estimates)}/{rounds_per_scenario} regressed")
            for name, lower, point, upper in estimates:
                print(
                    f"    {name}: median change "
                    f"[{lower:+.2f}% {point:+.2f}% {upper:+.2f}%]"
                )
        return 1

    print(
        f"PASS: all {expected} benchmark comparisons stayed within the "
        f"{max_regression_percent:.2f}% regression limit."
    )
    return 0


def parser() -> argparse.ArgumentParser:
    """Build the command-line parser."""
    cli = argparse.ArgumentParser(description=__doc__)
    subcommands = cli.add_subparsers(dest="command", required=True)

    baseline = subcommands.add_parser(
        "verify-baseline", help="verify a complete named baseline"
    )
    baseline.add_argument("--criterion-dir", type=Path, required=True)
    baseline.add_argument("--name", required=True)
    baseline.add_argument("--expected", type=int, required=True)

    check = subcommands.add_parser(
        "check", help="check current Criterion comparisons for regressions"
    )
    check.add_argument("--criterion-dir", type=Path, required=True)
    check.add_argument("--since", type=float, required=True)
    check.add_argument("--expected", type=int, required=True)
    check.add_argument("--rounds-per-scenario", type=int, required=True)
    check.add_argument("--max-regression-percent", type=float, required=True)
    return cli


def main(arguments: list[str] | None = None) -> int:
    """Run the requested baseline or regression validation."""
    options = parser().parse_args(arguments)
    if options.command == "verify-baseline":
        return verify_baseline(
            options.criterion_dir,
            options.name,
            options.expected,
        )
    return check_regressions(
        options.criterion_dir,
        options.since,
        options.expected,
        options.rounds_per_scenario,
        options.max_regression_percent,
    )


if __name__ == "__main__":
    raise SystemExit(main())
